/** Ask, then block: letters stop both ways, and any on their way are returned. */
export function confirmBlock(letterOrPerson, blocked) {
  if (blocked && !window.confirm(String(t('letter.block_confirm', {
    name: letterOrPerson.displayName
  })))) return Promise.resolve(false);
  return call('POST', '/blocks', {
    user: letterOrPerson.id,
    blocked
  }).then(() => {
    app.alerts.show({
      type: 'success'
    }, blocked ? t('letter.blocked', {
      name: letterOrPerson.displayName
    }) : t('letter.unblocked', {
      name: letterOrPerson.displayName
    }));
    return true;
  });
}
